INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63200915', 63200915, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Belanja Bahan', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 1120000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Safety Box 1 BOX x 1 KL ( 5, BOX, @ 25000 ); 2. Sarung tangan disposible 1 BOX x 1 KL ( 5, BOX, @ 125000 ); 3. Penggandaan formulir 1 PT x 1 KL ( 5, PT, @ 23000 ); 4. Lancet 30 BH x 1 KL ( 150, BH, @ 200 ); 5. Alcohol swab 1 BOX x 1 KL ( 5, BOX, @ 45000 );', 'Pekerjaan ini meliputi penyediaan bahan medis habis pakai (BMHP) dan sarana pendukung administrasi yang diperlukan untuk pelaksanaan survei deteksi dini serta pemetaan faktor risiko penyakit HIV AIDS di wilayah kerja Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan alat pengambilan sampel darah tepi berupa lancet steril dan kapas alkohol (alcohol swab), sarung tangan disposibel untuk pelindungan tenaga kesehatan, serta wadah pembuangan limbah tajam (safety box) guna menjamin keamanan kerja sesuai prosedur biosafety. Selain itu, pekerjaan ini mencakup penggandaan formulir kuesioner dan lembar kerja untuk pendataan identitas serta riwayat risiko responden di lapangan. Spesifikasi barang diwajibkan memenuhi standar alat kesehatan yang berlaku, steril, dan memiliki izin edar resmi untuk menjamin akurasi hasil pemeriksaan serta mencegah infeksi silang. Pengadaan ini bertujuan untuk memastikan seluruh rangkaian kegiatan surveilans HIV AIDS berjalan dengan aman, higienis, dan terdokumentasi secara sistematis guna mendukung upaya pencegahan dan pengendalian penyakit menular sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 780732);
