INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63200888', 63200888, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Belanja Bahan Pelaksanaan Survei Faktor Risiko Penyakit TB', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 3060000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Masker 2 BOX x 1 KL ( 24, BOX, @ 50000 ); 2. Fotokopi Kuesioner 100 LBR x 1 KL ( 1200, BH, @ 300 ); 3. Sarung Tangan Disposable 1 BOX x 1 KL ( 12, BOX, @ 125000 );', 'Pekerjaan ini meliputi penyediaan sarana perlindungan diri dan logistik administrasi yang diperlukan untuk mendukung kelancaran survei lapangan serta identifikasi faktor risiko penyakit Tuberkulosis (TB) di wilayah kerja Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan masker medis dan sarung tangan sekali pakai (disposable) sebagai alat pelindung diri standar bagi petugas guna memitigasi risiko penularan melalui udara (airborne) dan kontak fisik saat berinteraksi dengan responden atau lingkungan survei. Selain itu, pekerjaan ini mencakup penggandaan atau fotokopi kuesioner sebagai instrumen utama dalam pengumpulan data riwayat kesehatan dan kondisi lingkungan masyarakat. Spesifikasi bahan diutamakan pada kualitas yang memenuhi standar kesehatan, nyaman digunakan dalam durasi lama, serta hasil cetakan formulir yang jelas dan mudah dibaca. Pengadaan ini bertujuan untuk menjamin keamanan dan keselamatan petugas lapangan serta memastikan proses pendataan faktor risiko TB terlaksana secara sistematis, akurat, dan akuntabel sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 780780);
