INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63201083', 63201083, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Belanja Bahan Pelaksanaan Pengendalian Faktor Risiko Penyakit DBD', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 7644000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Pengadaan campuran insektisida 19 LTR x 1 HA x 1 KL ( 266, LTR, @ 16000 ); 2. Pengadaan bahan bakar mesin fog 3 LTR x 1 HA x 1 KL ( 42, LTR, @ 14000 ); 3. Konsumsi pendamping dan kader 4 OR x 1 KL ( 56, OH, @ 50000 );', 'Pekerjaan ini meliputi penyediaan bahan kimia, bahan bakar, dan dukungan logistik yang diperlukan untuk pelaksanaan tindakan pengendalian vektor DBD di wilayah kerja Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan campuran insektisida yang memiliki izin edar resmi dan terdaftar untuk penggunaan kesehatan masyarakat, penyediaan bahan bakar (BBM) sebagai pelarut serta penggerak mesin pengasapan (fogging), serta penyediaan konsumsi berupa makan dan kudapan bagi petugas pendamping dan kader kesehatan yang bertugas di lapangan. Spesifikasi pekerjaan menekankan pada aspek keamanan bahan kimia terhadap lingkungan, kesesuaian bahan bakar dengan spesifikasi mesin, serta penyediaan konsumsi yang higienis untuk menjaga kondisi fisik tim pelaksana. Pengadaan ini bertujuan untuk menjamin kesiapan logistik intervensi secara menyeluruh guna memutus rantai penularan penyakit DBD secara efektif, tepat sasaran, dan akuntabel sesuai dengan standar operasional prosedur pengendalian vektor sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 781754);
