INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63201000', 63201000, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Belanja Bahan Pelaksanaan Pengendalian Faktor Risiko Penyakit Diare', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 5112000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Bahan bakar (BBM) kendaraan 3 LTR x 1 HA ( 108, LTR, @ 14000 ); 2. Konsumsi petugas dan/atau kader 2 OR x 1 KL ( 72, OH, @ 50000 );', 'Pekerjaan ini meliputi penyediaan sarana pendukung operasional berupa bahan bakar kendaraan dan penyediaan konsumsi bagi petugas serta kader dalam rangka pelaksanaan kegiatan pengendalian faktor risiko penyakit Diare di wilayah kerja Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pekerjaan mencakup penyediaan Bahan Bakar Minyak (BBM) untuk mobilisasi tim ke lokasi intervensi/titik pengamatan, serta penyediaan konsumsi (makan dan kudapan) bagi petugas dan kader kesehatan yang terlibat langsung dalam kegiatan lapangan, penyuluhan, maupun inspeksi sanitasi. Spesifikasi pekerjaan mengharuskan penyediaan bahan bakar sesuai tarif resmi pemerintah dan penyediaan konsumsi yang memenuhi standar kebersihan serta gizi seimbang guna menjaga kondisi fisik petugas selama menjalankan tugas. Pengadaan ini bertujuan untuk menjamin kelancaran mobilitas dan keberlangsungan koordinasi lapangan dalam upaya pemutusan rantai penularan penyakit Diare, sehingga kegiatan pengendalian dapat terlaksana secara efektif, tepat sasaran, dan akuntabel sesuai jadwal operasional tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 782146);
