INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63200953', 63200953, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI KEKARANTINAAN KESEHATAN KELAS I TANJUNG PINANG', 'Belanja Bahan Pelaksanaan Survei Faktor Risiko Penyakit Malaria', 'Barang', 'Pengadaan Langsung', 'Kepulauan Riau, Tanjung Pinang (Kota)', 360000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. ATK 1 PT x 1 KL ( 18, PT, @ 20000 );', 'Pekerjaan ini meliputi penyediaan sarana Alat Tulis Kantor (ATK) dan logistik pencatatan data yang diperlukan untuk mendukung kegiatan surveilans serta pemetaan lokasi perindukan vektor Malaria di wilayah kerja Balai Kekarantinaan Kesehatan (BKK). Ruang lingkup pengadaan mencakup penyediaan formulir identifikasi penderita dan hasil pemeriksaan laboratorium, buku catatan lapangan khusus yang tahan terhadap cuaca, alat tulis permanen untuk penandaan pada kaca sediaan darah (slide), serta map/kontainer plastik untuk penyimpanan dokumen agar tidak rusak selama proses pengambilan data di lapangan. Spesifikasi teknis mengutamakan kualitas barang yang fungsional dan awet guna memastikan seluruh data hasil survei faktor risiko dapat terdokumentasi dengan jelas, sistematis, dan mudah dibaca untuk keperluan analisis data kesehatan. Pengadaan ini bertujuan untuk menjamin ketersediaan sarana administrasi yang memadai bagi petugas lapangan, sehingga laporan perkembangan situasi Malaria dapat disusun secara akurat dan tepat waktu sepanjang tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 782933);
